export function selectCertificates(records,category,query,sort){const q=query.trim().toLowerCase();return records.filter(c=>(category==='All'||c.category===category)&&[c.title,c.issuer,c.category].some(v=>v.toLowerCase().includes(q))).sort((a,b)=>sort==='az'?a.title.localeCompare(b.title):sort==='oldest'?a.date.localeCompare(b.date)||a.id-b.id:b.date.localeCompare(a.date)||a.id-b.id);}
